-- S109 — In-app booking notification inbox + lifecycle/security corrections
-- (KANEL × ALCEDO online bookings, Phase 5 completion + hardening). Additive
-- migration; NOT applied to production; public path stays flagged off.
--
-- Corrections to s108 (owner review of PR #135):
--   1. A real in-app notification INBOX for managers/admins (read/unread, deep
--      link to the reservation) — independent of web-push delivery.
--   3. Only KANEL public-booking reservations trigger the automated workflow:
--      gate on a reliable origin marker (public_token is not null), not source.
--   4. A rejected pending request => 'declined' (distinct email), a cancelled
--      confirmed booking => 'cancelled', and no_show is never a guest cancellation.
--   5a. The status RPC now checks the database feature flag.
--   5c. Rate limiting is consumed in its own committed transaction (a public
--       gateway RPC the edge calls first), so failed requests still count.
--   5f. A conflicting idempotency payload no longer returns the existing token.
--   6.  Outbox de-duplication (a unique dedupe key) so repeated lifecycle events
--       cannot later send duplicate guest emails.

-- 1. In-app inbox (sealed; one row per manager/admin, per event) ---------------
create table if not exists atlas_private.booking_notifications (
  id uuid primary key default gen_random_uuid(),
  audience_user_id uuid not null,
  reservation_id uuid references atlas_private.reservations(id) on delete cascade,
  kind text not null check (kind in ('request','approved','declined','changed','cancelled','no_show')),
  title text not null check (char_length(title) between 1 and 160),
  body text not null check (char_length(body) between 1 and 500),
  route text not null default 'bookings',
  read_at timestamptz,
  created_at timestamptz not null default now()
);
alter table atlas_private.booking_notifications enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname='atlas_private'
      and tablename='booking_notifications' and policyname='service role manages booking notifications') then
    create policy "service role manages booking notifications" on atlas_private.booking_notifications
      for all to service_role using (true) with check (true);
  end if;
end $$;
revoke all on atlas_private.booking_notifications from public, anon, authenticated;
grant all on atlas_private.booking_notifications to service_role;
create index if not exists booking_notifications_inbox_idx
  on atlas_private.booking_notifications (audience_user_id, read_at, created_at desc);

-- 2. Staff RPCs: list my booking notifications, and mark read (manager/admin) --
create or replace function public.atlas_bookings_notifications(
  p_actor_id uuid, p_actor_role text, p_limit integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  n integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  items jsonb;
  unread integer;
begin
  perform atlas_private.booking_require_manager(p_actor_id, p_actor_role);
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', x.id, 'reservation_id', x.reservation_id, 'kind', x.kind,
      'title', x.title, 'body', x.body, 'route', x.route,
      'read', x.read_at is not null, 'created_at', x.created_at
    ) order by x.created_at desc), '[]'::jsonb)
  into items
  from (
    select * from atlas_private.booking_notifications
    where audience_user_id = p_actor_id
    order by created_at desc limit n
  ) x;
  select pg_catalog.count(*) into unread from atlas_private.booking_notifications
   where audience_user_id = p_actor_id and read_at is null;
  return pg_catalog.jsonb_build_object('items', items, 'unread', unread);
end
$function$;
revoke all on function public.atlas_bookings_notifications(uuid, text, integer) from public, anon, authenticated;
grant execute on function public.atlas_bookings_notifications(uuid, text, integer) to service_role;

create or replace function public.atlas_bookings_notification_read(
  p_actor_id uuid, p_actor_role text, p_ids jsonb default null, p_all boolean default false
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare ids uuid[]; updated integer;
begin
  perform atlas_private.booking_require_manager(p_actor_id, p_actor_role);
  if p_all then
    update atlas_private.booking_notifications set read_at = pg_catalog.now()
     where audience_user_id = p_actor_id and read_at is null;
    get diagnostics updated = row_count;
  else
    if pg_catalog.jsonb_typeof(p_ids) <> 'array' then
      raise exception 'Choose notifications to mark read.' using errcode = '22023', hint = 'atlas:invalid_request';
    end if;
    select pg_catalog.array_agg((value #>> '{}')::uuid) into ids from pg_catalog.jsonb_array_elements(p_ids) value;
    update atlas_private.booking_notifications set read_at = pg_catalog.now()
     where audience_user_id = p_actor_id and id = any(ids) and read_at is null;
    get diagnostics updated = row_count;
  end if;
  return pg_catalog.jsonb_build_object('updated', updated);
end
$function$;
revoke all on function public.atlas_bookings_notification_read(uuid, text, jsonb, boolean) from public, anon, authenticated;
grant execute on function public.atlas_bookings_notification_read(uuid, text, jsonb, boolean) to service_role;

-- 3-4-6. Outbox: add 'declined' + a de-dup key ---------------------------------
alter table atlas_private.booking_email_outbox drop constraint if exists booking_email_outbox_kind_check;
alter table atlas_private.booking_email_outbox add constraint booking_email_outbox_kind_check
  check (kind in ('request_received','confirmed','declined','changed','cancelled'));
alter table atlas_private.booking_email_outbox add column if not exists dedupe_key text;
-- Non-partial: NULLs are distinct (legacy rows never conflict), and ON CONFLICT
-- (dedupe_key) needs a full unique index to arbitrate the de-dup.
create unique index if not exists booking_email_outbox_dedupe_idx
  on atlas_private.booking_email_outbox (dedupe_key);

-- Reworked lifecycle notifier: KANEL public bookings only (public_token marker),
-- writing the in-app inbox AND the email outbox, with correct rejection vs
-- cancellation and no_show handling, and de-duplicated emails.
create or replace function atlas_private.booking_lifecycle_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  s atlas_private.booking_settings;
  from_email text;
  g text;
  m record;
  inbox_kind text;
  inbox_title text;
  inbox_body text;
  email_kind text;
  subject text;
  body text;
  dkey text;
begin
  -- Origin marker: only reservations created by the KANEL public-booking system
  -- carry a public_token. Legacy VÁ Bar / Sinna rows never do.
  if new.public_token is null then return new; end if;
  select * into s from atlas_private.booking_settings where id = true;
  from_email := coalesce(s.booking_email_from, 'kanel@kanel.is');
  g := nullif(new.guest_email, '');

  if tg_op = 'INSERT' and new.status = 'requested' then
    inbox_kind := 'request'; inbox_title := 'New booking request';
    inbox_body := pg_catalog.left(coalesce(new.guest_name,'A guest') || ' · party of ' || new.party_size, 480);
    email_kind := 'request_received'; subject := 'We’ve received your booking request';
    body := 'Thank you. Your request (' || new.booking_reference || ') is awaiting confirmation by our team.';
  elsif tg_op = 'UPDATE' and new.status is distinct from old.status then
    if new.status = 'confirmed' then
      inbox_kind := 'approved'; inbox_title := 'Booking approved';
      inbox_body := coalesce(new.guest_name,'A guest') || ' · ' || new.booking_reference;
      email_kind := 'confirmed'; subject := 'Your booking is confirmed';
      body := 'Your booking ' || new.booking_reference || ' is confirmed. We look forward to welcoming you.';
    elsif new.status = 'cancelled' and old.status = 'requested' then
      -- A pending request that staff turned down is a rejection, not a cancellation.
      inbox_kind := 'declined'; inbox_title := 'Request declined';
      inbox_body := coalesce(new.guest_name,'A guest') || ' · ' || new.booking_reference;
      email_kind := 'declined'; subject := 'About your booking request';
      body := 'We’re sorry — we couldn’t accommodate request ' || new.booking_reference || '. Please contact us for other times.';
    elsif new.status = 'cancelled' then
      inbox_kind := 'cancelled'; inbox_title := 'Booking cancelled';
      inbox_body := coalesce(new.guest_name,'A guest') || ' · ' || new.booking_reference;
      email_kind := 'cancelled'; subject := 'Your booking has been cancelled';
      body := 'Your booking ' || new.booking_reference || ' has been cancelled. Please contact us to rebook.';
    elsif new.status = 'no_show' then
      -- Staff record only; the guest is NOT emailed and it is not a cancellation.
      inbox_kind := 'no_show'; inbox_title := 'Marked no-show';
      inbox_body := coalesce(new.guest_name,'A guest') || ' · ' || new.booking_reference;
      email_kind := null;
    else
      return new;  -- intermediate staff statuses (arrived/seated) are not notified
    end if;
  elsif tg_op = 'UPDATE' and (new.start_at is distinct from old.start_at or new.party_size is distinct from old.party_size) then
    inbox_kind := 'changed'; inbox_title := 'Booking updated';
    inbox_body := coalesce(new.guest_name,'A guest') || ' · ' || new.booking_reference;
    email_kind := 'changed'; subject := 'Your booking has been updated';
    body := 'Your booking ' || new.booking_reference || ' has been updated. See the latest details with your reference.';
  else
    return new;
  end if;

  -- In-app inbox for every event (works without push delivery), plus an optional
  -- phone push for the actionable NEW REQUEST only — routed to 'bookings' so the
  -- service worker opens the booking, not Messages. Both target active
  -- managers/admins only.
  for m in select id from public.profiles where active and role in ('admin','manager') loop
    insert into atlas_private.booking_notifications (audience_user_id, reservation_id, kind, title, body, route)
    values (m.id, new.id, inbox_kind, inbox_title, inbox_body, 'bookings');
    if tg_op = 'INSERT' and new.status = 'requested' then
      insert into atlas_private.push_notification_queue (audience_user_id, event_type, title, body, route, object_id)
      values (m.id, 'booking_request', inbox_title, inbox_body, 'bookings', new.id);
    end if;
  end loop;

  -- Guest email (queued only). De-duplicated so a repeated identical event can
  -- never enqueue a second copy; a genuine new change (new time/party/status)
  -- gets a distinct key and so a distinct email.
  if email_kind is not null and g is not null then
    dkey := pg_catalog.md5(new.id::text || ':' || email_kind || ':' || new.status || ':'
      || coalesce(new.start_at::text,'') || ':' || coalesce(new.party_size::text,''));
    insert into atlas_private.booking_email_outbox (reservation_id, kind, to_email, from_email, subject, body, dedupe_key)
    values (new.id, email_kind, g, from_email, subject, body, dkey)
    on conflict (dedupe_key) do nothing;
  end if;
  return new;
end
$function$;
revoke all on function atlas_private.booking_lifecycle_notify() from public, anon, authenticated;

-- 5c. Rate limit consumed in its OWN transaction (the edge calls this first, so
-- a flood of requests that later fail still counts). Per-action limits.
create or replace function public.atlas_public_booking_rate(p_fingerprint text, p_action text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare lim integer; win integer; ok boolean;
begin
  if p_action = 'request' then lim := 8; win := 600;
  elsif p_action = 'availability' then lim := 60; win := 60;
  elsif p_action = 'status' then lim := 30; win := 60;
  else lim := 30; win := 60; end if;
  ok := atlas_private.booking_public_rate_ok(coalesce(p_fingerprint,'') || ':' || p_action, lim, win);
  return pg_catalog.jsonb_build_object('ok', ok);
end
$function$;
revoke all on function public.atlas_public_booking_rate(text, text) from public, anon, authenticated;
grant execute on function public.atlas_public_booking_rate(text, text) to service_role;

-- 5a. Status RPC now checks the database feature flag too.
create or replace function public.atlas_public_booking_status(p_token text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare r atlas_private.reservations; s atlas_private.booking_settings;
begin
  select * into s from atlas_private.booking_settings where id = true;
  if not s.public_online_enabled then
    raise exception 'Online booking is not available right now.' using errcode = '22023', hint = 'atlas:disabled';
  end if;
  if p_token is null or pg_catalog.length(p_token) < 24 then
    raise exception 'Booking not found.' using errcode = 'P0002', hint = 'atlas:not_found';
  end if;
  select * into r from atlas_private.reservations where public_token = p_token;
  if r.id is null then
    raise exception 'Booking not found.' using errcode = 'P0002', hint = 'atlas:not_found';
  end if;
  return pg_catalog.jsonb_build_object(
    'reference', r.booking_reference, 'status', r.status,
    'start_at', r.start_at, 'party_size', r.party_size);
end
$function$;
revoke all on function public.atlas_public_booking_status(text) from public, anon, authenticated;
grant execute on function public.atlas_public_booking_status(text) to service_role;

-- 5f. Request RPC: idempotency now rejects a CONFLICTING reuse (a different
-- party/time under the same key returns a conflict, never the stored token), and
-- rate limiting moves to the edge-committed RPC above (no internal double-count).
create or replace function public.atlas_public_booking_request(p_payload jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  p jsonb := coalesce(p_payload, '{}'::jsonb);
  s atlas_private.booking_settings;
  tz text := coalesce(nullif(p->>'tz',''), 'Atlantic/Reykjavik');
  v_party integer := (p->>'party_size')::int;
  v_start timestamptz := (p->>'start_at')::timestamptz;
  v_dur integer := 120;
  v_end timestamptz;
  v_name text := nullif(p->>'guest_name','');
  v_phone text := nullif(p->>'guest_phone','');
  v_email text := nullif(p->>'guest_email','');
  v_requests text := nullif(p->>'guest_requests','');
  v_fingerprint text := nullif(p->>'fingerprint','');
  v_raw_idem text := nullif(p->>'idempotency_key','');
  v_idem text;
  v_area uuid;
  run uuid[];
  tid uuid;
  v_ref text;
  v_token text;
  v_id uuid := gen_random_uuid();
  existing atlas_private.reservations;
begin
  select * into s from atlas_private.booking_settings where id = true;
  if not s.public_online_enabled then
    raise exception 'Online booking is not available right now.' using errcode = '22023', hint = 'atlas:disabled';
  end if;

  if v_party is null or v_start is null or v_name is null then
    raise exception 'A name, party size and time are required.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if v_party < 1 or v_party > coalesce(s.max_party_online, 4) then
    raise exception 'Online booking is for parties of 1 to %.', coalesce(s.max_party_online, 4) using errcode = '22023', hint = 'atlas:invalid_request';
  end if;

  if v_raw_idem is not null then
    v_idem := 'web:' || coalesce(v_fingerprint, 'anon') || ':' || v_raw_idem;
    select * into existing from atlas_private.reservations where idempotency_key = v_idem;
    if existing.id is not null then
      -- A replay must match the original request; a conflicting reuse is refused
      -- and never discloses the stored booking's token.
      if existing.party_size <> v_party or existing.start_at <> v_start then
        raise exception 'That request conflicts with an earlier one.' using errcode = '22023', hint = 'atlas:invalid_request';
      end if;
      return pg_catalog.jsonb_build_object('reference', existing.booking_reference,
        'public_token', existing.public_token, 'status', existing.status);
    end if;
  end if;

  if v_start < pg_catalog.now()
     or v_start > pg_catalog.now() + pg_catalog.make_interval(days => coalesce(s.advance_days, 90)) then
    raise exception 'That date is outside the booking window.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if not atlas_private.booking_within_hours(v_start, v_dur, tz) then
    raise exception 'That time is outside opening hours.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;

  select id into v_area from atlas_private.booking_areas
   where online_bookable and is_active order by display_order limit 1;
  if v_area is null then
    raise exception 'Online booking is not available right now.' using errcode = '22023', hint = 'atlas:disabled';
  end if;

  v_end := v_start + pg_catalog.make_interval(mins => v_dur);

  perform 1 from atlas_private.booking_tables t where t.area_id = v_area order by t.id for update;
  run := atlas_private.booking_find_contiguous_tables(v_area, v_party, v_start, v_end, null);
  if run is null then
    raise exception 'That time is no longer available.' using errcode = '23505', hint = 'atlas:conflict';
  end if;

  v_ref := atlas_private.booking_public_reference();
  v_token := atlas_private.booking_public_token();

  insert into atlas_private.reservations
    (id, source, status, start_at, end_at, party_size, guest_name, guest_phone, guest_email,
     guest_requests, booking_reference, idempotency_key, public_token, area_id)
  values (v_id, 'web', 'requested', v_start, v_end, v_party, v_name, v_phone, v_email,
     v_requests, v_ref, v_idem, v_token, v_area);

  foreach tid in array run loop
    insert into atlas_private.booking_holds (table_id, reservation_id, start_at, end_at, reason, expires_at)
    values (tid, v_id, v_start, v_end, 'web_pending',
            pg_catalog.now() + pg_catalog.make_interval(mins => coalesce(s.public_hold_minutes, 15)));
  end loop;

  insert into atlas_private.reservation_status_history (reservation_id, from_status, to_status, note)
  values (v_id, null, 'requested', 'public online request');
  insert into atlas_private.booking_events (event_type, reservation_id, payload)
  values ('reservation_created', v_id, pg_catalog.jsonb_build_object('party_size', v_party, 'source', 'web', 'channel', 'public'));

  return pg_catalog.jsonb_build_object('reference', v_ref, 'public_token', v_token, 'status', 'requested');
end
$function$;
revoke all on function public.atlas_public_booking_request(jsonb) from public, anon, authenticated;
grant execute on function public.atlas_public_booking_request(jsonb) to service_role;
-- <<< end of migration file <<<

insert into supabase_migrations.schema_migrations(version, name, statements)
values ('20261026090000', 's109_booking_notifications_inbox', array[]::text[]);

